class Solution {
    using P = array<double, 2>;
    struct Circle {
        double x, y, r;
    };
    double dist(P a, P b) {
        return hypot(a[0] - b[0], a[1] - b[1]);
    }
    bool contains(Circle c, P p) {
        return hypot(c.x - p[0], c.y - p[1]) <= c.r + 1e-8;
    }
    Circle diameter(P a, P b) {
        return {(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, dist(a, b) / 2};
    }
    Circle through(P a, P b, P c) {
        double d = 2 * (a[0] * (b[1] - c[1]) +
                        b[0] * (c[1] - a[1]) + c[0] * (a[1] - b[1]));
        if (abs(d) < 1e-12) {
            Circle best = diameter(a, b);
            for (Circle candidate : {diameter(a, c), diameter(b, c)}) {
                if (contains(candidate, a) && contains(candidate, b) &&
                    contains(candidate, c) && candidate.r < best.r) {
                    best = candidate;
                }
            }
            return best;
        }
        double aa = a[0] * a[0] + a[1] * a[1];
        double bb = b[0] * b[0] + b[1] * b[1];
        double cc = c[0] * c[0] + c[1] * c[1];
        double x = (aa * (b[1] - c[1]) + bb * (c[1] - a[1]) +
                    cc * (a[1] - b[1])) / d;
        double y = (aa * (c[0] - b[0]) + bb * (a[0] - c[0]) +
                    cc * (b[0] - a[0])) / d;
        return {x, y, hypot(x - a[0], y - a[1])};
    }
public:
    vector<double> outerTrees(vector<vector<int>>& trees) {
        vector<P> points;
        for (const auto& p : trees) {
            points.push_back({(double)p[0], (double)p[1]});
        }
        mt19937 gen(42);
        shuffle(points.begin(), points.end(), gen);
        Circle c = {0, 0, -1};
        for (int i = 0; i < (int)points.size(); ++i) {
            if (c.r >= 0 && contains(c, points[i])) {
                continue;
            }
            c = {points[i][0], points[i][1], 0};
            for (int j = 0; j < i; ++j) {
                if (contains(c, points[j])) {
                    continue;
                }
                c = diameter(points[i], points[j]);
                for (int k = 0; k < j; ++k) {
                    if (!contains(c, points[k])) {
                        c = through(points[i], points[j], points[k]);
                    }
                }
            }
        }
        return {c.x, c.y, c.r};
    }
};
